        return np.clip(x, a_min=lb, a_max=ub)

    def objective(x):
        return func(x)

    x = np.random.uniform(lb, ub, size=(dim,))
    T = 10.0
    cooling_rate = 0.99

    for _ in range(budget):
        x_new = x + rng.normal(0, 1, size=(dim,))
